pseudocode:
let n = grid.length, swaps = 0;
let counts = grid.map(row => row.lastIndexOf(1));
for (let i = 0; i < n; i++) {
  let target = n - 1 - i;
  let j = i;
  while (j < n && counts[j] > target) j++;
  if (j === n) return -1;
  while (j > i) {
    [counts[j], counts[j-1]] = [counts[j-1], counts[j]];
    swaps++;
    j--;
  }
}
return swaps;
